INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('550f63c0-0129-410d-b548-e854e0b1ca80', 'a1b2c3d4-2222-4000-8000-000000000002', 4, 'O Rosário Contemplativo', 'Maria como mestra de oração', '{"intro": "O Ros\u00e1rio n\u00e3o \u00e9 mera repeti\u00e7\u00e3o \u2014 \u00e9 contempla\u00e7\u00e3o dos mist\u00e9rios de Cristo atrav\u00e9s dos olhos de Maria. S\u00e3o Jo\u00e3o Paulo II, em sua enc\u00edclica Rosarium Virginis Mariae, chamou o Ros\u00e1rio de \"comp\u00eandio do Evangelho\". Cada dezena \u00e9 uma janela para um momento da vida de Jesus. O segredo \u00e9 contemplar, n\u00e3o apenas contar. Quando rezado com o cora\u00e7\u00e3o, o Ros\u00e1rio se torna uma escola de ora\u00e7\u00e3o profunda.", "prayer": "Maria, minha M\u00e3e, ensina-me a contemplar teu Filho como tu o contemplavas. Que cada Ave-Maria seja um passo mais perto do Cora\u00e7\u00e3o de Jesus. Am\u00e9m.", "practice": "Reze uma dezena do Ros\u00e1rio (10 Ave-Marias) contemplando um mist\u00e9rio. Antes de come\u00e7ar, leia a passagem b\u00edblica correspondente. Imagine-se na cena.", "scripture": "\"Maria, por\u00e9m, guardava todas estas coisas, meditando-as no seu cora\u00e7\u00e3o.\" \u2014 Lc 2,19", "reflection": "Qual mist\u00e9rio do Ros\u00e1rio mais fala ao seu cora\u00e7\u00e3o hoje? Por que esse mist\u00e9rio te toca?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;